"""Text normalization helpers."""


import re


def slugify(s):
    """Turn a human title into a URL slug (lowercase, words joined by hyphens)."""
    # Convert to lowercase and extract only alphanumeric characters and spaces
    # Then split on non-alphanumeric characters, filter out empty strings, and join with hyphens
    words = re.split(r'[^a-zA-Z0-9]+', s.lower())
    return '-'.join(filter(None, words))


def titlecase(s):
    return " ".join(w.capitalize() for w in s.split())
